// Command themegen records palette data and generates typed role accessors.
package main

import (
	"archive/zip"
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type color struct {
	name, key       string
	line, nightLine int
}

var declaration = regexp.MustCompile(`^([A-Za-z][A-Za-z0-9]*):\s*([^;]+);`)
var hoverSuffix = regexp.MustCompile(`Over($|[A-Z])`)
var roleWords = strings.NewReplacer("Bg", "Background", "Fg", "Foreground", "Ripple", "Pressed", "Mono", "Code", "Date", "Timestamp")

func main() {
	root := flag.String("sources", "", "Telegram source checkout parent（读上游源码时要给）")
	out := flag.String("out", ".", "repository root")
	metricsOnly := flag.Bool("metrics-only", false, "generate metrics from the recorded clean-room table without reading upstream sources")
	recorded := flag.Bool("recorded", false, "regenerate colors and metrics from repository records only")
	flag.Parse()
	if *recorded {
		generateRecordedColors(*out)
		generateMetrics(*out)
		return
	}
	if *metricsOnly {
		generateMetrics(*out)
		return
	}
	palette := mustRead(filepath.Join(*root, "lib_ui/ui/colors.palette"))
	zr, err := zip.OpenReader(filepath.Join(*root, "tdesktop/Telegram/Resources/night.tdesktop-theme"))
	must(err)
	defer zr.Close()
	var night []byte
	for _, f := range zr.File {
		if f.Name == "colors.tdesktop-theme" {
			r, e := f.Open()
			must(e)
			night, e = io.ReadAll(r)
			must(e)
			must(r.Close())
		}
	}
	if night == nil {
		panic("night palette missing")
	}
	nightValues, nightLines := parse(night)
	values, lines := parse(palette)
	merged := make(map[string]string, len(values))
	for k, v := range values {
		merged[k] = v
	}
	matchedNight := 0
	for k, v := range nightValues {
		if _, ok := values[k]; ok {
			merged[k] = v
			matchedNight++
		}
	}
	var rows []color
	for name := range values {
		rows = append(rows, color{name, role(name), lines[name], nightLines[name]})
	}
	for key, source := range extraRoles {
		rows = append(rows, color{source, key, lines[source], nightLines[source]})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].key < rows[j].key })
	seen := map[string]bool{}
	for _, r := range rows {
		if seen[r.key] {
			panic("duplicate role " + r.key)
		}
		seen[r.key] = true
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by internal/cmd/themegen; DO NOT EDIT.\npackage theme\n\nimport \"github.com/egoist/mygo/ui\"\n\n")
	keys := make([]string, len(rows))
	for i, r := range rows {
		keys[i] = r.key
	}
	for _, s := range outlineColors {
		keys = append(keys, s[0])
	}
	accessors(&b, "Colors", "ui.Color", keys)
	// The two outline colors are recorded by the clean-room tabs specification.
	// Keep them outside the upstream palette and preserve their typed indices.
	b.WriteString("var colorSpecs = [...]colorSpec{\n")
	for _, r := range rows {
		light := resolve(r.name, values, map[string]bool{})
		dark := resolve(r.name, merged, map[string]bool{})
		if source, ok := extraRoles[r.key]; ok {
			light = "@" + role(source)
			dark = light
		}
		fmt.Fprintf(&b, "{%q,%q,%q}, // %s:%d\n", r.key, light, dark, r.name, r.line)
	}
	for _, s := range outlineColors {
		fmt.Fprintf(&b, "{%q,%q,%q}, // paint/tabs.md#info岛状变体\n", s[0], s[1], s[1])
	}
	b.WriteString("}\n")
	saveGo(*out, "theme/colors_gen.go", b.Bytes())
	var doc bytes.Buffer
	doc.WriteString("# 颜色来源\n\n生成命令：`go run ./internal/cmd/themegen`。版本见 README.md。\n\n覆盖 lib_ui 的 colors.palette 全部声明，含登录、设置、通话、钱包等扩展角色；不复制素材。别名展开为 RGBA，`| fallback` 的左侧是浅色声明值。night 使用同名覆盖，缺项继承浅色声明，再在合并表内解析别名；不含背景图片。\n\n| MewTypeUI 键 | Telegram 常量 | 浅色来源 | 展开值 | night 来源 | night 展开值 |\n|---|---|---|---|---|---|\n")
	for _, r := range rows {
		source := "继承浅色 / 合并别名"
		if r.nightLine > 0 {
			source = fmt.Sprintf("night.tdesktop-theme/colors.tdesktop-theme:%d", r.nightLine)
		}
		fmt.Fprintf(&doc, "| `%s` | `%s` | ui/colors.palette:%d | `%s` | %s | `%s` |\n", r.key, r.name, r.line, resolve(r.name, values, map[string]bool{}), source, resolve(r.name, merged, map[string]bool{}))
	}
	for _, s := range outlineColors {
		fmt.Fprintf(&doc, "| `%s` | outline RGB | paint/tabs.md; info_profile_tabs_strip.cpp:34-42 | `%s` | 同源；alpha由主题指标控制 | `%s` |\n", s[0], s[1], s[1])
	}
	fmt.Fprintf(&doc, "\n共 %d 个 palette 角色，加 %d 个用途映射。night 中 %d 个同名声明覆盖当前 palette，%d 个当前角色继承合并表，%d 个旧声明不公开。映射选择见 exceptions.md。\n", len(values), len(extraRoles)+len(outlineColors), matchedNight, len(values)-matchedNight, len(nightValues)-matchedNight)
	save(*out, "docs/reference/theme-colors.md", doc.Bytes())
	generateMetrics(*out)
	fmt.Printf("Generated %d palette roles + %d semantic mappings; night: %d matched, %d inherited, %d retired keys.\n", len(values), len(extraRoles)+len(outlineColors), matchedNight, len(values)-matchedNight, len(nightValues)-matchedNight)
}

func parse(data []byte) (map[string]string, map[string]int) {
	values := map[string]string{}
	lines := map[string]int{}
	for i, line := range strings.Split(string(data), "\n") {
		m := declaration.FindStringSubmatch(strings.TrimSpace(line))
		if m == nil {
			continue
		}
		value := strings.TrimSpace(strings.Split(m[2], "|")[0])
		values[m[1]] = value
		lines[m[1]] = i + 1
	}
	return values, lines
}
func resolve(name string, values map[string]string, visiting map[string]bool) string {
	value, ok := values[name]
	if !ok {
		panic("missing source " + name)
	}
	if visiting[name] {
		panic("source cycle " + name)
	}
	if strings.HasPrefix(value, "#") {
		if len(value) == 7 {
			value += "ff"
		}
		return strings.ToLower(value)
	}
	visiting[name] = true
	result := resolve(value, values, visiting)
	delete(visiting, name)
	return result
}
func role(name string) string {
	exact := map[string]string{
		"windowFg": "window.text", "windowBg": "window.background", "windowSubTextFg": "window.mutedText",
		"inputBorderFg": "control.border", "activeLineFg": "control.focus", "topBarBg": "header.background",
		"historyTextInFg": "message.in.text", "historyTextOutFg": "message.out.text",
		"historyTextInFgSelected": "message.in.textSelected", "historyTextOutFgSelected": "message.out.textSelected",
		"historyLinkInFg": "message.in.link", "historyLinkOutFg": "message.out.link",
		"historyLinkInFgSelected": "message.in.linkSelected", "historyLinkOutFgSelected": "message.out.linkSelected",
		"msgInReplyBarColor": "quote.in.bar", "msgInReplyBarSelColor": "quote.in.barSelected",
		"msgOutReplyBarColor": "quote.out.bar", "msgOutReplyBarSelColor": "quote.out.barSelected",
		"msgImgReplyBarColor": "quote.media.bar", "msgServiceBg": "service.background", "msgServiceBgSelected": "service.backgroundSelected", "msgServiceFg": "service.text",
		"historyUnreadBarBg": "service.unreadBackground", "historyUnreadBarFg": "service.unreadText", "historyUnreadBarBorder": "service.unreadBorder",
		"historyComposeAreaBg": "compose.background", "historyComposeAreaFg": "compose.text",
		"placeholderFg": "compose.placeholder", "placeholderFgActive": "compose.placeholderFocused",
	}
	if v, ok := exact[name]; ok {
		return v
	}
	prefixes := [][2]string{
		{"historyCompose", "compose."}, {"historySending", "message.sending"}, {"historySend", "compose.send"},
		{"historyReply", "compose.reply"}, {"historyPinned", "compose.pinned"}, {"historyToDown", "navigation.toLatest"},
		{"historyScrollBar", "scrollbar.chatThumb"}, {"historyScroll", "scrollbar.chatTrack"},
		{"scrollBar", "scrollbar.thumb"}, {"scroll", "scrollbar.track"},
		{"msgIn", "message.in."}, {"msgOut", "message.out."}, {"historyPeer", "avatar."},
		{"history", "message."}, {"msg", "message."}, {"dialogs", "conversation."}, {"sideBar", "sidebar."},
		{"activeButton", "control.primary"}, {"lightButton", "control.surface"}, {"attentionButton", "control.danger"},
		{"menu", "menu."}, {"tooltip", "tooltip."}, {"window", "window."}, {"title", "titlebar."},
		{"botKb", "keyboard."}, {"emoji", "emoji."}, {"sticker", "sticker."}, {"mediaview", "viewer."},
		{"mediaPlayer", "player."}, {"media", "media."}, {"mainMenu", "navigation.mainMenu"}, {"searched", "search."},
		{"image", "media.image"}, {"toast", "toast."}, {"groupCall", "groupCall."}, {"call", "call."},
		{"box", "dialog."}, {"contacts", "contact."}, {"intro", "intro."}, {"settings", "settings."},
		{"notificationsBox", "notification.settings"}, {"notification", "notification."}, {"wallet", "wallet."},
		{"premium", "premium."}, {"statistics", "statistics."}, {"credits", "credits."}, {"rank", "rank."},
	}
	group, rest := "control.", name
	for _, p := range prefixes {
		if strings.HasPrefix(name, p[0]) {
			group, rest = p[1], strings.TrimPrefix(name, p[0])
			break
		}
	}
	rest = roleWords.Replace(rest)
	rest = hoverSuffix.ReplaceAllString(rest, "Hover${1}")
	if rest == "" {
		rest = "base"
	}
	if rest[0] >= '0' && rest[0] <= '9' {
		rest = "peer" + rest
	}
	rest = strings.ToLower(rest[:1]) + rest[1:]
	if !strings.HasSuffix(group, ".") {
		rest = strings.ToUpper(rest[:1]) + rest[1:]
	}
	return group + rest
}

type node struct {
	children map[string]*node
	index    int
	leaf     bool
}

func accessors(b *bytes.Buffer, root, typ string, keys []string) {
	tree := &node{children: map[string]*node{}}
	for i, k := range keys {
		n := tree
		for _, p := range strings.Split(k, ".") {
			if n.children[p] == nil {
				n.children[p] = &node{children: map[string]*node{}}
			}
			n = n.children[p]
		}
		n.index = i
		n.leaf = true
	}
	fmt.Fprintf(b, "type %s struct { values [%d]%s }\n", root, len(keys), typ)
	var visit func(*node, string, bool)
	visit = func(n *node, typeName string, isRoot bool) {
		if !isRoot {
			fmt.Fprintf(b, "type %s struct { data *%s }\n", typeName, root)
		}
		names := make([]string, 0, len(n.children))
		for k := range n.children {
			names = append(names, k)
		}
		sort.Strings(names)
		for _, k := range names {
			child := n.children[k]
			method := strings.ToUpper(k[:1]) + k[1:]
			receiver := "v.data"
			if isRoot {
				receiver = "v"
			}
			recvType := typeName
			if isRoot {
				recvType = "*" + typeName
			}
			if child.leaf {
				fmt.Fprintf(b, "func (v %s) %s() %s { return %s.values[%d] }\n", recvType, method, typ, receiver, child.index)
			} else {
				next := typeName + method
				fmt.Fprintf(b, "func (v %s) %s() %s { return %s{data:%s} }\n", recvType, method, next, next, receiver)
				visit(child, next, false)
			}
		}
	}
	visit(tree, root, true)
}
func must(err error) {
	if err != nil {
		panic(err)
	}
}
func mustRead(path string) []byte { b, e := os.ReadFile(path); must(e); return b }
func save(root, path string, data []byte) {
	p := filepath.Join(root, path)
	must(os.MkdirAll(filepath.Dir(p), 0755))
	must(os.WriteFile(p, data, 0644))
}
func saveGo(root, path string, data []byte) {
	formatted, e := format.Source(data)
	if e != nil {
		fmt.Println(string(data))
	}
	must(e)
	save(root, path, formatted)
}
